style.css:
@-moz-document url-prefix("https://www.youtube.") {
/* Fond global */
  html, body, #content, ytd-app {
    background-color: #000 !important;
    color: #e0e0e0 !important;
  }

  /* En-tête (barre du haut) */
  ytd-masthead, #container.ytd-masthead {
    background-color: #0b0b0b !important;
    border-bottom: 1px solid #111 !important;
  }

  /* Barre de recherche */
  input#search {
    background-color: #111 !important;
    color: #e0e0e0 !important;
    border: 1px solid #222 !important;
    border-radius: 20px !important;
    padding: 6px 12px !important;
  }
  input#search::placeholder {
    color: #777 !important;
  }

  /* Icônes (loupe, micro, menu, etc.) */
  yt-icon, #search-icon-legacy, #voice-search-button {
    color: #aaa !important;
    fill: #aaa !important;
  }
  yt-icon:hover, #search-icon-legacy:hover, #voice-search-button:hover {
    color: #fff !important;
    fill: #fff !important;
  }

  /* Sidebar gauche */
  ytd-guide-section-renderer, #guide-content {
    background-color: #000 !important;
    color: #ccc !important;
  }
  ytd-guide-entry-renderer:hover {
    background-color: #111 !important;
  }

  /* Titres vidéos */
  #video-title {
    color: #f1f1f1 !important;
  }
  #video-title:hover {
    color: #fff !important;
  }

  /* Textes secondaires (vues, chaînes, etc.) */
  #metadata-line, #byline, #channel-name, ytd-video-meta-block, yt-formatted-string {
    color: #999 !important;
  }

  /* Boutons like/dislike/subscribe */
  ytd-toggle-button-renderer, ytd-subscribe-button-renderer {
    background: #111 !important;
    border: 1px solid #222 !important;
    border-radius: 18px !important;
    color: #e0e0e0 !important;
  }
  ytd-toggle-button-renderer:hover, ytd-subscribe-button-renderer:hover {
    background: #222 !important;
  }

  /* Lecteur vidéo (autour du player) */
  #player-theater-container, #player-container {
    background-color: #000 !important;
  }

  /* Commentaires */
  ytd-comments, ytd-comment-thread-renderer {
    background: #000 !important;
    color: #ccc !important;
  }
  ytd-comment-thread-renderer:hover {
    background: #111 !important;
  }

  /* Footer */
  #footer-container {
    background: #000 !important;
    color: #666 !important;
  }
}
